def dihedral_shapes(coords):
    # coords local arbitrary; normalize bounding box after each transformation
    out=[]
    for k in range(4):
        for refl in [False, True]:
            pts=set(coords)
            # mirror left-right around coordinate range before rot; transformations around min bbox
            maxc=max(c for r,c in pts); maxr=max(r for r,c in pts)
            if refl: pts={(r,maxc-c) for r,c in pts}
            for _ in range(k):
                maxr=max(r for r,c in pts)
                pts={(c,maxr-r) for r,c in pts} # CW rectangular
            minr=min(r for r,c in pts); minc=min(c for r,c in pts)
            pts={(r-minr,c-minc) for r,c in pts}
            if pts not in [x[0] for x in out]: out.append((pts,(k,refl)))
    return out

def scan_translations(shape, cloud, h,w):
    mh=max(r for r,c in shape); mw=max(c for r,c in shape)
    result=[]
    for dr in range(h-mh):
      for dc in range(w-mw):
        placed={(r+dr,c+dc) for r,c in shape}
        result.append((len(placed&cloud),placed&cloud,dr,dc,placed))
    return sorted(result,key=lambda x:x[0],reverse=True)
